import React, { useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, NavLink } from 'react-router-dom';
import axios from 'axios';
import Dashboard from './Dashboard';
import MalwareLab from './MalwareLab';
import VulnScanner from './VulnScanner';
import Auth from './Auth';
import Admin from './Admin';

function App() {
  useEffect(() => {
    axios
      .get('/api/auth/csrf-token')
      .then((res) => {
        if (res.data?.csrf_token) {
          axios.defaults.headers.common['X-CSRFToken'] = res.data.csrf_token;
        }
      })
      .catch(() => {
        // CSRF token endpoint is optional; ignore failures.
      });

    const jwt = localStorage.getItem('jwt_token');
    if (jwt) {
      axios.defaults.headers.common['Authorization'] = `Bearer ${jwt}`;
    }
  }, []);

  return (
    <Router>
      <nav className="navbar navbar-expand-lg navbar-dark bg-dark">
        <div className="container-fluid">
          <NavLink className="navbar-brand" to="/">CyberShield Lab</NavLink>
          <button className="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#mainNav">
            <span className="navbar-toggler-icon" />
          </button>
          <div className="collapse navbar-collapse" id="mainNav">
            <ul className="navbar-nav me-auto mb-2 mb-lg-0">
              <li className="nav-item"><NavLink className="nav-link" to="/">Dashboard</NavLink></li>
              <li className="nav-item"><NavLink className="nav-link" to="/malware">Malware Lab</NavLink></li>
              <li className="nav-item"><NavLink className="nav-link" to="/vuln">Vuln Scanner</NavLink></li>
              <li className="nav-item"><NavLink className="nav-link" to="/auth">Auth Demo</NavLink></li>
              <li className="nav-item"><NavLink className="nav-link" to="/admin">Admin</NavLink></li>
            </ul>
          </div>
        </div>
      </nav>

      <div className="container mt-4">
        <Routes>
          <Route path="/" element={<Dashboard />} />
          <Route path="/malware" element={<MalwareLab />} />
          <Route path="/vuln" element={<VulnScanner />} />
          <Route path="/auth" element={<Auth />} />
          <Route path="/admin" element={<Admin />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
